// Embedded public-domain example datasets and example queries for Scrapsheets.

export const Col = (val, key) => {
  const [name, type] = val.split("::");
  return {
    name: name,
    type: type ?? "text",
    key: key.toString(),
  };
};

export const Table = (cols, ...rows) => ({
  type: "table",
  data: [cols, ...rows],
});

export const QuerySql = (cols, code, ...examples) => ({
  type: "query",
  data: [
    {
      lang: "sql",
      code,
      cols,
      args: {},
      examples,
    },
  ],
});

