const colors = Table(
  ["swatch::image", "name::text", "hex::text", "red::int", "green::int", "blue::int", "hue::num"].map(Col),
  ...CSS_COLORS.map(([name, hex]) => {
    const r = parseInt(hex.slice(1, 3), 16);
    const g = parseInt(hex.slice(3, 5), 16);
    const b = parseInt(hex.slice(5, 7), 16);
    const max = Math.max(r, g, b);
    const d = max - Math.min(r, g, b);
    const h = d === 0 ? 0 : max === r ? ((g - b) / d + 6) % 6 : max === g ? (b - r) / d + 2 : (r - g) / d + 4;
    return [
      "data:image/svg+xml,<svg xmlns='http://www.w3.org/2000/svg' width='40' height='16'><rect width='40' height='16' fill='%23" + hex.slice(1) + "'/></svg>",
      name,
      hex,
      r,
      g,
      b,
      Math.round(h * 600) / 10,
    ];
  }),
);

