// DNS resource record types, by IANA number. A zone export, a passive-DNS feed
// and a certificate-transparency pipeline all identify a record by type, and
// the numeric form is what a wire capture carries.
const dnsRecords = Table(
  ["type::text", "number::int", "name::text", "purpose::text"].map(Col),
  ["A", 1, "Host address", "Points a name at an IPv4 address"],
  ["NS", 2, "Name server", "Delegates a zone to a name server"],
  ["CNAME", 5, "Canonical name", "Aliases one name to another"],
  ["SOA", 6, "Start of authority", "Carries the zone serial and refresh timers"],
  ["PTR", 12, "Pointer", "Maps an address back to a name"],
  ["MX", 15, "Mail exchange", "Names the mail servers for a domain"],
  ["TXT", 16, "Text", "Carries SPF, DKIM and domain verification strings"],
  ["AAAA", 28, "IPv6 host address", "Points a name at an IPv6 address"],
  ["SRV", 33, "Service locator", "Gives host and port for a named service"],
  ["NAPTR", 35, "Naming authority pointer", "Rewrites a name, used by ENUM and SIP"],
  ["CERT", 37, "Certificate", "Stores a certificate in the DNS"],
  ["DNAME", 39, "Delegation name", "Aliases a whole subtree"],
  ["OPT", 41, "Option pseudo-record", "Carries EDNS(0) options on a query"],
  ["DS", 43, "Delegation signer", "Links a child zone's key into the parent"],
  ["SSHFP", 44, "SSH fingerprint", "Publishes an SSH host key fingerprint"],
  ["IPSECKEY", 45, "IPsec key", "Publishes an IPsec public key"],
  ["RRSIG", 46, "Signature", "Signs a record set for DNSSEC"],
  ["NSEC", 47, "Next secure", "Proves a name does not exist"],
  ["DNSKEY", 48, "DNSSEC key", "Publishes a zone signing key"],
  ["NSEC3", 50, "Next secure v3", "Proves non-existence without zone walking"],
  ["NSEC3PARAM", 51, "NSEC3 parameters", "Holds the NSEC3 hash parameters"],
  ["TLSA", 52, "TLS association", "Pins a TLS certificate under DANE"],
  ["SMIMEA", 53, "S/MIME association", "Pins an S/MIME certificate"],
  ["CDS", 59, "Child DS", "Child's request to update the parent DS"],
  ["CDNSKEY", 60, "Child DNSKEY", "Child's request to update the parent key"],
  ["OPENPGPKEY", 61, "OpenPGP key", "Publishes an OpenPGP public key"],
  ["CSYNC", 62, "Child-to-parent sync", "Asks the parent to copy NS and address records"],
  ["ZONEMD", 63, "Zone message digest", "Checksums a whole zone file"],
  ["SVCB", 64, "Service binding", "Advertises alternative service endpoints"],
  ["HTTPS", 65, "HTTPS binding", "SVCB for HTTPS, carries ALPN and ECH"],
  ["SPF", 99, "Sender policy", "Obsolete; SPF lives in TXT now"],
  ["AXFR", 252, "Full zone transfer", "Query type only, never stored"],
  ["ANY", 255, "All records", "Query type only, widely refused"],
  ["URI", 256, "URI", "Maps a name to a URI"],
  ["CAA", 257, "Certification authority authorization", "Names who may issue certificates"],
);

